//! GENERATED by the milestone-7 golden capture -- do not hand-edit.
//!
//! Every value below is the reference engine's own output. None of
//! milestone 7's five functions is on `UME`'s public export or its `_test`
//! one, so the capture adds them (with `buildSite`, `makeGraph`, `addStreet`,
//! `placeAnchors` and both route builders, which the fixtures need) by a
//! single anchored replacement of the `return {` line, asserted to match
//! exactly once. The frozen reference file itself is untouched.
//!
//! Two further anchored insertions, each asserted to match exactly once:
//! `buildWall` is stubbed to record its calls and return (it is milestone
//! 10's, and the Rust side runs the identical stub as
//! `RecordingWallBuilder`), and `grow`'s epoch loop gets a per-epoch
//! observer so a divergence localises to an epoch.
//!
//! `graph_hash` is the reference's OWN `fnv1a` over its own canonical dump of
//! every node and edge, with each double written as its exact 64 bits
//! (`nodes: x,y,adj.` joined `;`, then `#`, then `edges: a,b,cls,w,epoch,alive`).
//! `grid_hash` is milestone 6's convention, unchanged.

#![allow(clippy::approx_constant, clippy::unreadable_literal, clippy::excessive_precision)]

/// A water raster + centreline, exactly as the capture handed it to `buildSite`.
pub struct WaterSpec {
    pub mask: &'static [u8],
    pub dt: &'static [f64],
    pub mw: usize,
    pub mh: usize,
    pub cell_m: f64,
    pub river_path: &'static [f64],
    pub river_width_m: f64,
    pub river_order: f64,
    pub sea_lake_cells: f64,
}

/// A heightfield raster, likewise.
pub struct TerrainSpec {
    pub grid: &'static [f64],
    pub mw: usize,
    pub mh: usize,
    pub cell_m: f64,
    pub h_min: f64,
    pub h_max: f64,
}

/// `rules.street` + `rules.settlement`, the eighteen fields `grow` reads (plus
/// `dead_end_bias`, which it does not, carried so the table is the whole
/// object). `None` on a case means the case passed **no** `opts.rules` at all,
/// which is the `opts.rules || DEFAULT_RULES` fallback.
pub struct RulesSpec {
    pub branch_angle_jitter: f64,
    pub continuation_jitter: f64,
    pub exploration_start: f64,
    pub exploration_decay: f64,
    pub exploration_minimum: f64,
    pub segment_length_median: f64,
    pub segment_length_variance: f64,
    pub pierce_chance: f64,
    pub junction_angle_limit: f64,
    pub market_gradient_decay: f64,
    pub parallel_street_spacing: f64,
    pub dead_end_bias: f64,
    pub bridgehead_distance: f64,
    pub bridgehead_probability: f64,
    pub wall_generation_threshold: f64,
    pub wall_generation_min_age_gap: f64,
    pub wall_generation_extramural_share: f64,
    pub max_wall_generations: f64,
    pub carrying_capacity_weight: f64,
}

/// A hand-laid seed street: `(ax, ay, bx, by, cls, w, epoch)`.
pub type SeedStreet = (f64, f64, f64, f64, &'static str, f64, i32);

/// A pre-set `wallState`, for the fixtures that need a circuit `buildWall`
/// would otherwise have had to build.
pub struct WallSpec {
    pub ring: &'static [f64],
    pub gates: &'static [f64],
    /// `None` is the reference's absent `landArc`.
    pub land_arc: Option<&'static [f64]>,
    pub epoch: i32,
    /// `-1` means the field was absent, which `grow` reads as 1.
    pub generation: i64,
}

/// One captured supersession record.
pub struct HistorySpec {
    pub ring_len: usize,
    pub gates_len: usize,
    pub land_arc_len: i64,
    pub epoch: i32,
    pub generation: u32,
    pub fill_fraction: f64,
    pub exterior_nodes: usize,
}

/// One captured scenario.
pub struct Case {
    pub name: &'static str,
    // --- site + pre-grow graph ---
    pub site_seed: u32,
    pub kind: &'static str,
    pub anchor_seed: u32,
    /// The site box: 1700 x 1250 unless the scenario needs a small one to
    /// make the four 40 m box margins observable.
    pub wm: f64,
    pub hm: f64,
    pub water: Option<&'static WaterSpec>,
    pub terrain: Option<&'static TerrainSpec>,
    /// `Some` drives `buildPrimariesFromPaths`; `None` with an empty
    /// `seed_streets` drives `buildPrimaries`.
    pub paths: Option<&'static [&'static [f64]]>,
    pub seed_streets: &'static [SeedStreet],
    pub pre_nodes: usize,
    pub pre_edges: usize,
    pub pre_hash: u32,
    pub market: (f64, f64),
    // --- grow inputs ---
    pub grow_seed: u32,
    pub epochs: i32,
    pub target_len: f64,
    pub max_rf: f64,
    pub walls: bool,
    pub wall_generations: bool,
    /// `None` means `opts.settlementAge` was absent.
    pub settlement_age: Option<f64>,
    /// `None` means no `opts.harbour` at all; flat `[x, y, ...]` otherwise.
    pub harbour_quay: Option<&'static [f64]>,
    pub rules: Option<&'static RulesSpec>,
    pub wall0: Option<&'static WallSpec>,
    // --- captured output ---
    pub placed_len: f64,
    /// `placedLen` as of the end of each epoch.
    pub epoch_len: &'static [f64],
    pub epoch_nodes: &'static [usize],
    pub epoch_edges: &'static [usize],
    pub epoch_hash: &'static [u32],
    /// `(x, y, adj)`
    pub nodes: &'static [(f64, f64, &'static [usize])],
    /// `(a, b, cls, w, epoch, alive)`
    pub edges: &'static [(usize, usize, &'static str, f64, i32, bool)],
    /// Whether `nodes`/`edges` carry the full dump. `graph_hash` pins every
    /// node and edge bit for bit either way; the dump is redundant
    /// strictness kept for the smaller scenarios so a failure is readable.
    pub dumped: bool,
    pub graph_hash: u32,
    /// `fnv1a` over every edge's provenance string, joined by U+0001. The
    /// strings are built by concatenation from the `explore` flag and the
    /// epoch, so this pins the Exploration/Densification split and the epoch
    /// stamp of every street the town ever laid.
    pub prov_hash: u32,
    pub grid_cells: usize,
    pub grid_hash: u32,
    /// `(epoch, generation-as-read)` per `buildWall` call.
    pub wall_calls: &'static [(i32, u32)],
    pub history: &'static [HistorySpec],
    /// `wallState.generation` afterwards; `-1` if still absent.
    pub end_generation: i64,
}

